task.situation:
가상의 은행 이체 서비스에서 '계정계 입금 호출이 실패한 건의 실패 이력이 하나도 남지 않는다'는 운영 문의가 들어왔다. 실패 이력은 본 거래가 롤백되더라도 반드시 남아야 하는 요구사항이다. 스택은 Spring Boot + MyBatis + Oracle이고 트랜잭션 매니저는 DataSourceTransactionManager, 기본 프록시 모드다. 커넥션 풀 최대 크기는 20, 피크 시 동시 이체 요청은 약 15건이다.

[코드]
@Service
public class TransferService {
    @Transactional
    public void transfer(TransferRequest req) {
        ledgerMapper.insertWithdraw(req);          // 출금 원장 INSERT
        try {
            coreClient.deposit(req);               // 외부 계정계 입금 호출 (평균 300ms, 최대 5초)
        } catch (CoreApiException e) {             // RuntimeException 하위
            saveFailureHistory(req, e);
            throw e;
        }
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void saveFailureHistory(TransferRequest req, Exception e) {
        failureMapper.insert(req.getTxId(), e.getMessage());
    }
}

